Here is the schema design:

```sql
CREATE TABLE transactions (
    id uuid PRIMARY KEY,
    client_id uuid,
    timestamp timestamp with time zone,
    amount numeric,
    description text,
    metadata jsonb,
    embedding vector(128)
);

CREATE INDEX transactions_id ON transactions USING pgvector;
CREATE INDEX transactions_client_id ON transactions USING pgvector;
CREATE INDEX transactions_timestamp ON transactions USING pgvector;
CREATE INDEX transactions_amount ON transactions USING pgvector;
CREATE INDEX transactions_description ON transactions USING pgvector;
CREATE INDEX transactions_metadata ON transactions USING pgvector

